INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('barbara-graham-tue-11th-nov-2014-at-12-16', 'Barbara Graham', 'Tue 11th Nov 2014 at 12:16', 'Well done salty lamps , had a really pleasant on line shopping experience, I am delighted with the special offer of rock salt lamp and candle holders plus the Himalayan crystal bath salts , my goods arrived two days after ordering, will definitely share this with friends and family .', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sonia-fri-19th-sep-2014-at-16-08', 'Sonia', 'Fri 19th Sep 2014 at 16:08', 'Ordered the 1kg of salt while on special offer. Order arrived very promptly. This is my second order now and I''ve been extremely pleased both times! Thank you', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('linda-tue-2nd-sep-2014-at-17-52', 'Linda', 'Tue 2nd Sep 2014 at 17:52', 'Really quick service, well packaged and only took 3 day''s to arrive! I ordered three large tea light holders-''natural effect'' (1 for me and two others for presents) and they look amazing unlit, can''t wait to ''light them up''. Well done!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('eileen-tue-8th-jul-2014-at-22-23', 'Eileen', 'Tue 8th Jul 2014 at 22:23', 'I love these products!! Delivery was quick. However the bulb was crushed in the package and one of the bobbles on the base was completely detached from the lamp. Not really BIG problems....but i am used to the service being perfect! It will not stop me from ordering from you again because the products ARE good.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('carmela-ranieri-wed-14th-may-2014-at-12-09', 'Carmela Ranieri', 'Wed 14th May 2014 at 12:09', 'I just received the Salty Lamp & two candle holders I ordered and I am very impressed with the quality of these items. I ordered them for their health benefits, however, as an interior designer, I would say that they would compliment any scheme as they are natural looking and very beautiful. The culinary salt is also top quality. Highly recommended!', '', NULL, 0, 0, 1, '');
