INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('david-rawle-mon-10th-mar-2014-at-20-50', 'david rawle', 'Mon 10th Mar 2014 at 20:50', 'Very pleased with products and the customer service was excellent. Will buy again', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('chrissie-wed-5th-mar-2014-at-20-54', 'Chrissie', 'Wed 5th Mar 2014 at 20:54', 'So pleased to have found Salty Lamps. I love the Himalayan Crystal Bath Salts ... wouldn''t be without them now. Great product from a very reliable company.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('thomas-alber-fri-28th-feb-2014-at-21-18', 'Thomas Alber', 'Fri 28th Feb 2014 at 21:18', 'A little piece of heaven on earth...I purchased a couple of lamps and tea light holders a while back and am almost certain I sleep better when the bed side lamp has been on for half an hour or so before bed to warm and purify the surrounding air!! Easily highly recommended!!', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sabira-fri-28th-feb-2014-at-20-43', 'Sabira', 'Fri 28th Feb 2014 at 20:43', 'Excellent service time after time. Have been recommending you to all my patients. Thank you and keep up the good work.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('umm-hajar-fri-28th-feb-2014-at-19-20', 'Umm Hajar', 'Fri 28th Feb 2014 at 19:20', 'Its a blessing to have a company such as Salty lamps as nowadays is hard to find good products for good value for money at the same time. I have converted all my family to replacing their table salt to the culinary himalyan salt, especially my mother who has high blood pressure. Im very please with your products and especially the quick delivery service. Thanks a bunch! Umm Hajar', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('julie-deans-fri-28th-feb-2014-at-13-45', 'Julie Deans', 'Fri 28th Feb 2014 at 13:45', 'My sister gave me a salty lamp for Christmas years ago and I have since bought quite a few. I absolutely love sitting with the nice orange glow and the first thing I do when I get in at night is switch on my salty lamps! I might consider buying one for my office!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('iain-duthie-thu-27th-feb-2014-at-21-33', 'Iain duthie', 'Thu 27th Feb 2014 at 21:33', 'We bought one at the winter wonderland and loved it since then we bought a further 2 for family and everyone loves them .', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('anne-close-thu-27th-feb-2014-at-19-30', 'anne close', 'Thu 27th Feb 2014 at 19:30', 'hello, I''ve always been extremely happy with Salty Lamps. There special offers are fantastic (tho I''m not sure I really benefit as I keep giving bags of salt away to family/friends!)Great service also and delivery. Have recommended to a few people. Only one thing I wasn''t happy with and that was that the bulb inside the salt lamp kept blowing, I guess because of the heat build up within enclosed space. To rectify this I now use an oven bulb and it lasts for ages. Maybe Salty Lamps would consider selling these instead of present bulbs.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('pauline-radestock-thu-27th-feb-2014-at-19-07', 'Pauline Radestock', 'Thu 27th Feb 2014 at 19:07', 'I bought my salty lamp after a recommendation from a friend.I switch it on whenever I am in the room and love the feeling of warmth and wellbeing I get from it. I have recommended it to several of my friends', '', NULL, 0, 0, 1, '');
