INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('gemma-binstead-thu-27th-feb-2014-at-11-09', 'Gemma Binstead', 'Thu 27th Feb 2014 at 11:09', 'I love Salty Lamp products. I have a candle holder and use the bath salts every time I have a bath. I would love more of the products, and I recommend them to everyone!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('rianne-thu-27th-feb-2014-at-10-06', 'Rianne', 'Thu 27th Feb 2014 at 10:06', 'I have ordered the salt lamps, candle holders and bath salt and I love them all! The lamps and candle holders look amazing and I love to have a warm bath knowing that I''m actually doing a good thing for my health/skin rather than harming with all toxic soaps/bath products. Thanks a lot Salty Lamps, I''m very happy with the service!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('valerie-thu-27th-feb-2014-at-09-20', 'Valerie', 'Thu 27th Feb 2014 at 09:20', 'Love all these products, I have candle holders and an electric lamp. Ordered some spare bulbs for my electric lamp and received a very quite delivery. They also look lovely. My daughter does reflexology and has them when doing treatments, and also they are very calming in my bedroom. We also use the bath crystals, which as I have knee arthritis help enormously.', '', NULL, 0, 0, 1, '');
