INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('angela-thu-27th-feb-2014-at-08-40', 'Angela', 'Thu 27th Feb 2014 at 08:40', 'Absolutely love these in my yoga studio. Put them in a bowl or deep plate for first use as condensation forms.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lois-thu-27th-feb-2014-at-08-14', 'Lois', 'Thu 27th Feb 2014 at 08:14', 'Thank you for your very speedy delivery and the great quality of your lamps. I use them in my treatment room and at home.', '', NULL, 0, 0, 1, '');
