INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sandy-wed-26th-feb-2014-at-19-34', 'Sandy', 'Wed 26th Feb 2014 at 19:34', 'I have bought himalayan rock salt from Salty Lamps four or five times, and have been really pleased with my goods every time! The delivery has always been very prompt, and the salt is always well packed and in perfect condition. Thank you for such wonderful quality and service!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('ursula-dekker-wed-26th-feb-2014-at-17-24', 'Ursula Dekker', 'Wed 26th Feb 2014 at 17:24', 'I use the salt on a daily basis in cooking, sole and salt baths and have found the healing properties incredible. I have recommended this product to so many friends and Salty Lamps have great combo offers to get all you need!', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('zorana-wed-26th-feb-2014-at-11-58', 'Zorana', 'Wed 26th Feb 2014 at 11:58', 'Thank you for fast delivery and excellent products. I bought Himalayan cooking satl and its great quality, good packing for easy storage too. Will order more and you have the best price. Thank you, Zorana(Cambridge)', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('mrs-hutchins-sat-18th-jan-2014-at-16-29', 'Mrs Hutchins', 'Sat 18th Jan 2014 at 16:29', 'Thank you Salty Lamps for a very fast delivery and your very generous offer of buy 1 get 1 free! I will def be using you again!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jana-wed-18th-dec-2013-at-20-39', 'Jana', 'Wed 18th Dec 2013 at 20:39', 'I love your products. This is the first time I ordered it from your website otherwise I usually buy them from the shop in London. The delivery was fast and it''s great to get 2 pack with the price of 1. Definitely will buy more soon!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('anthony-wed-20th-nov-2013-at-11-50', 'anthony', 'Wed 20th Nov 2013 at 11:50', 'I recommend to anyone with any level of tension in their physical body trying Himalayan Crystal Bath Salt, the results following the directions given are astounding and effective for up to a fortnight. Even if you arn''t aware of any bodily tension it is worth trying, as you might be surprised to discover how relaxed one can be. Beyond that the other benefits claimed are undoubtedly worth considering also. This is my second order, 1kg will suffice for 12 months usage and at this great price there is possibly no better bargain available anywhere. Many thanks - all the best. anthony', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('mark-fri-11th-oct-2013-at-16-44', 'Mark', 'Fri 11th Oct 2013 at 16:44', 'Salty Lamps gave a very fast service. Kept me informed as my order was processed/despatched. Were readily willing to resolve an issue, until I realised it was my mistake. Great service, recommended.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('riya-sun-28th-jul-2013-at-14-17', 'Riya', 'Sun 28th Jul 2013 at 14:17', 'My husband and I brought lamps, candle holders, edible salt and a soap bar at the Vegetarian fair. I have had a longstanding dry skin problem on my back for the past 7 years and I have only used the salty soap bar 5 times and my back has totally cleared up! I no longer need to use creams or steroids. I am shocked! I have tried everything. I have noticed you don''t sell the soap bars and the balls on your website. Will I be able to order the soap from you again? Are the bath rock crystals you sell the same as the soap? Thank you for your time - and thank you- from the bottom of my heart- for helping to clear up my exzema!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('samantha-hutchinson-wed-5th-jun-2013-at-21-25', 'Samantha Hutchinson', 'Wed 5th Jun 2013 at 21:25', 'The bath salts have been a treasured discovery for us. Since using them in my daughter''s bath, her eczema is considerably better (and almost non-existent at the moment). We have awful hard London water, but since using the salts, her eczema doesn''t ''flare'' in angry red blotches when she gets in the bath, and the mineral salts seem to have helped the healing of her skin barrier. I am very grateful to the person who suggested these, and tell everyone I encounter with eczema. They are certainly not a cure, and I know from experience that eczema is a very complex and personal condition, but the salts have been very effective for my daughter''s condition. Easy ordering and prompt delivery. Thanks Salty Lamps.', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sue-wed-29th-may-2013-at-08-23', 'Sue', 'Wed 29th May 2013 at 08:23', 'The Himalayan salty lamps/candle holders are stunning and very special. They are so eye catching and calming to watch. Fantastic value, I am truly over the moon with these Salty Lamps. SO PRECIOUS and SO UNIQUE.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('ann-marie-goode-fri-24th-may-2013-at-20-17', 'Ann Marie Goode', 'Fri 24th May 2013 at 20:17', 'They are great products at fantastic prices i especially love my candel holders. Always a quick and reliable service!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('mr-t-thu-23rd-may-2013-at-17-43', 'Mr T', 'Thu 23rd May 2013 at 17:43', 'Great product, price and delivery', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('suezen-thu-23rd-may-2013-at-16-55', 'Suezen', 'Thu 23rd May 2013 at 16:55', 'Absolutely delighted with another purchase from Salty Lamps. These are beautiful additions to any room, enhancing both the look and the ambiance. Many thanks also for speedy delivery and expert packaging.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('david-rawle-thu-23rd-may-2013-at-09-00', 'david rawle', 'Thu 23rd May 2013 at 09:00', 'very pleased with product and the customer service was excellent. One of my products was damaged in transit and salty lamps were quick to apologise and replace the broken product. Excellent service.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('charlene-wed-22nd-may-2013-at-22-50', 'Charlene', 'Wed 22nd May 2013 at 22:50', 'Order dispatched quickly and packaged well thank you. i liked the leaflet that came with the candle that explained the benefits of the Salt. The salt candle is a beautiful natural product and looks amazing with a tea light in it. It instantly makes the room feel cosier and gives off a lovely light. My boyfriend also bought me the plug in lamp as a present for me. It is lovely, especially if you want a nice warm glow when you''re watching a film and don''t want the big lights on! Very happy, excellent products and value, would recommend.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jessy-zhang-wed-22nd-may-2013-at-22-25', 'jessy zhang', 'Wed 22nd May 2013 at 22:25', 'very good products i bought from salty lamps,really fast delivery and impressive customer service.highly recommand', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('zorana-wed-22nd-may-2013-at-22-23', 'Zorana', 'Wed 22nd May 2013 at 22:23', 'Site is great, and service is fantastic. I bought Himalayian salt and it was very good price and good offer. It arrived faster then I expected. Thank you. I will be back for more.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('mona-thu-4th-apr-2013-at-14-10', 'Mona', 'Thu 4th Apr 2013 at 14:10', 'I wanted to thank Salty Lamps for promptly dealing with the problem I was having with the cord of my lamp. They sent me a new one in the post and I was really please with the product. It all works fine now.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('clare-wed-3rd-apr-2013-at-13-54', 'clare', 'Wed 3rd Apr 2013 at 13:54', 'Great site, lovely products and excellent service! Ordered some candle holders and a lamp a few weeks ago - all look beautiful - and am now ordering loads more for friends who all love them too! Thanks for all your help! C', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('catherine-from-kent-fri-11th-jan-2013-at-12-58', 'Catherine from Kent', 'Fri 11th Jan 2013 at 12:58', 'I ordered 2 lamps before Christmas. They arrived promptly. First lamp was for myself and when I plugged it in, the fuse blew. I contacted Customer Service and they were very helpful , called me back and sent two new plug fuses in the post , in time for Christmas . My gift lamp''s fuse blew also, but luckily I had a spare fuse to give them. Thanks to such an efficient service I have no complaints at all.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('carlt-jones-wed-5th-dec-2012-at-15-21', 'carlt jones', 'Wed 5th Dec 2012 at 15:21', 'Wow! Ordered yesterday, then realised I had ordered incorrectly. Phoned to change, left message and call was returned immediately. Brilliant service. Goods delivered today! Packed well and left exactly where instructed as I was out. This is how a Company that cares about customer service and quality make it in today''s market. Thank You!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('rachel-mon-5th-nov-2012-at-13-52', 'Rachel', 'Mon 5th Nov 2012 at 13:52', 'I bought a lamp at the yoga show whilst recoverring from pneumonia. I am also asthmatic and the fluid just wasn''t clearing from my lungs. I kept the salt lamp on overnight when I first got it and my lungs were clear in the morning. It was my first asthma attack free night in two months. I now keep the lamp on for a couple of hours before going to bed and even my asthma nurse is amazed at the difference. I will be buying more as gifts for friends and family.', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jackie-davis-fri-5th-oct-2012-at-09-34', 'Jackie Davis', 'Fri 5th Oct 2012 at 09:34', 'After purchasing our first Salty Lamp at Mind Body & Soul last weekend - I can honestly say I cannot believe how much better I feel after having it on in the bedroom for less than a week!! Most mornings I would blow my nose at least 6 or 7 times and feel very congested in the nasal region - and within 2 days of having the lamp on I am only blowing my nose once or sometimes twice and do not feel congested - in fact feel the airways are a lot clearer. I have told my colleagues at work and we have just purchased 6 more lamps between us - THANKS', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('nikki-mon-11th-jun-2012-at-22-15', 'Nikki', 'Mon 11th Jun 2012 at 22:15', 'I ordered the special offer £25.00 Salt lamp and 2 candle holders. Everything was brilliantly packaged to prevent any damage and delivery was very speedy indeed. I''d been looking for a good quality lamp for a long time I love how there is no big piece of wood attached to the lamp...I like how they have little feet that allow ventilation and present the lamps beauty all on its own. I will definately be purchasing again! :D x', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jane-thu-26th-apr-2012-at-12-04', 'Jane', 'Thu 26th Apr 2012 at 12:04', 'I HAVE 5 OF YOUR WONDERFUL SALT LAMPS, AND LOOK FORWARD TO SEEING YOU AT THE MIND BODY SPIRIT FESTIVAL AT EARLS COURT. PLEASE CAN WE HAVE A BIGGER PYRAMID SALT LAMP.....', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('veronica-thu-2nd-feb-2012-at-15-04', 'Veronica', 'Thu 2nd Feb 2012 at 15:04', 'Super service. Love the lamps. Ordering more for prezzies!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lorna-fri-16th-dec-2011-at-19-31', 'Lorna', 'Fri 16th Dec 2011 at 19:31', 'I absolutely love my salty lamp it''s so calming I feel instantly soothed by its orange glow. I got mine at an exhibition then ordered two more on line. I was worried that maybe I''d not like the second ones as much as they would be to pale but about two minutes after I''d ordered someone called me to ask if I''d like dark or pale. Totally great service and speedy delivery. Highly recommend :)', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lesley-lynch-thu-15th-dec-2011-at-15-34', 'Lesley Lynch', 'Thu 15th Dec 2011 at 15:34', 'Absolutely fantastic customer service, a fast and efficient response to my enquiry and very speedy delivery. The delivery cost was also excellent value as I ordered 3 salt lamps and 6 nightlights and the parcel was very heavy. I will certainly be doing business with Salty Lamps again and look forward to seeing them at Mind Body Spirit festival in London in May.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lesley-macnay-tue-23rd-aug-2011-at-22-31', 'Lesley MacNay', 'Tue 23rd Aug 2011 at 22:31', 'I''ve just received my new order of Himalayan bath crystals tonight, delivery is always efficient and the qulity of crystals are really good. I have found them to be great for cleansing my auric field and relaxing my body.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('curly-wurly-wed-10th-aug-2011-at-01-52', 'Curly Wurly', 'Wed 10th Aug 2011 at 01:52', 'I ordered the special offer(1 lamp and two candle holders)for myself and my friend and the order was delivered short. I sent an email on the Sunday, received a telephone call on the Monday and the missing items were delivered on the Wednesday! I am very happy with the efficient way this matter was dealt with. Would recommend buying from this site.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('bob-handy-mon-8th-aug-2011-at-19-48', 'bob handy', 'Mon 8th Aug 2011 at 19:48', 'I bought some candle holders at the ideal home show as i knew they would look good once the room was decorated.They do indeed so i bought 4 more and its really relaxing having them alight and the main light off.Our son liked them as well so he bought some for his house.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('pamela-mon-8th-aug-2011-at-18-43', 'Pamela', 'Mon 8th Aug 2011 at 18:43', 'I have used one of the egg shaped salt lamps for a few years now. I order the same for a friend''s birthday. It arrived within 2 days and she is delighted with it. Excellent service & an excellent product. Thank you!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('donna-wed-3rd-aug-2011-at-22-31', 'Donna', 'Wed 3rd Aug 2011 at 22:31', 'I purchased the lamp with 2 candle holders for a gift. Service could not have been better, and they arrived very very quickly. The reciepent is delighted with them and use them all the time. I purchased my lamp and one candle holder at the Ideal Home Show in London earlier in the year, I am very pleased with them and will be back to the web site for more.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('janis-c-wed-3rd-aug-2011-at-20-54', 'Janis C', 'Wed 3rd Aug 2011 at 20:54', 'I love the bath salts - very relaxing and healing for the skin. I also bought the lamps and some nightlight holders. Very happy with the purchase and the customer service.', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('john-b-wed-3rd-aug-2011-at-19-12', 'John B', 'Wed 3rd Aug 2011 at 19:12', 'Very pleased with the quality of service and the personal attention to customer satisfaction. Too early to comment properly on the effectiveness of the Salty Lamp and candle lamps but they are attractive and appear to be good value for money. Thank-you.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sally-jenkins-wed-3rd-aug-2011-at-15-51', 'Sally Jenkins', 'Wed 3rd Aug 2011 at 15:51', 'On this occasion I just order a power supply for a salt lamp and the service I received was excellent. I have ordered the actual lamps in the past and they are fantastic, i would definitely recommend them.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('natalie-wed-3rd-aug-2011-at-15-17', 'Natalie', 'Wed 3rd Aug 2011 at 15:17', 'We bought two sphere shaped lamps and absolutely love them. Would buy again.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('orit-wed-3rd-aug-2011-at-09-30', 'Orit', 'Wed 3rd Aug 2011 at 09:30', 'I bought my lamp in an exhibition few years ago. we love it and use it a lot.Recently I needed a bulb, decided to buy Himalayan bath salt as well and I''m very happy I did. The whole experience was a delight.The salt is wonderfull. Thank you very much. I''ll be back soon.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('matt-tue-17th-may-2011-at-14-21', 'matt', 'Tue 17th May 2011 at 14:21', 'I have used Salty Lamps several times now and have always had excellent service with rapid shipment. A credit to the online trading community!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lesley-andrews-tue-17th-may-2011-at-09-17', 'Lesley Andrews', 'Tue 17th May 2011 at 09:17', 'I have had two salty lamps (given as presents) for some time now, and was delighted to find that you supply bulbs and electrical components for them. As soon as they arrived I put them in my lamps and am currently enjoying the benefits. Many thanks for your very prompt service and email support, I''ll be back in the future to purchase more. Les', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('kim-wed-9th-mar-2011-at-12-41', 'kim', 'Wed 9th Mar 2011 at 12:41', 'i have been wanting a salt lamp for awhile and am so pleased i looked around and found salty lamps. i love my lamps and my candle light holders. i use them everyday and especially when i feel my mood isnt calm, once i turn on my lamp the energy around me changes to that of balance.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('kirstie-tue-8th-mar-2011-at-22-06', 'Kirstie', 'Tue 8th Mar 2011 at 22:06', 'I purchased a lamp and 2 candle holders in the special offer. They arrived quickly and are great- we love them! I have the lamp by my bed and move the candles around the house! Would recommend.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('maureen-tue-8th-mar-2011-at-07-27', 'Maureen', 'Tue 8th Mar 2011 at 07:27', 'I bought lamp and t-light holders at Christmas market in London,really liked them,but the bulb blew when I plugged it in.I did not contact Salty I just bought another bulb..a small annoyance but soon put right.Some weeks ago I bought more tea-light holders on web-site...the four for the price of three offer...delivery was fast and lights well packaged.These are natural, really beautiful lamps and I will be back for more.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('amanda-jane-luke-tue-8th-mar-2011-at-06-05', 'Amanda Jane Luke', 'Tue 8th Mar 2011 at 06:05', 'I brought one of the lamps and three of the candle holders. They are fantastic, they arrived quickly and well packaged. Love the leaflet you get with them explaining more about how the lamps work. It certainly had people talking in the office about them', '', NULL, 0, 0, 1, '');
