INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('karl-b-wed-19th-jan-2011-at-12-21', 'Karl B', 'Wed 19th Jan 2011 at 12:21', 'I bought two of the lamps and kept one for myself and gave the other away, they''re a great low light source and the person I gave one to loves it as much as I do. One minor annoyance though, was the bulb which came with mine unfortunately blew as soon as I turned it on.', '', NULL, 0, 0, 1, '');
