INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jennie-wed-22nd-dec-2010-at-10-11', 'Jennie', 'Wed 22nd Dec 2010 at 10:11', 'If only all companies had customer service as good as this. Simple to order, excellent communications, quick responses to any email queries. The lamps were well packed and had a good tracking service so I knew when to expect them. The lamps give a lovely glow to any room and have a calming influence. I also love the candle holders, which are wonderful when lit. A very happy customer who recommends Salty Lamps.', '', NULL, 0, 0, 1, '');
