INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lesley-mon-20th-dec-2010-at-18-58', 'Lesley', 'Mon 20th Dec 2010 at 18:58', 'I really like using the Himalayan crystal salt in my bath, it''s very relaxing.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('james-thu-16th-dec-2010-at-11-37', 'James', 'Thu 16th Dec 2010 at 11:37', 'I have owned 3 lamps for just over a year. I use them every night to relax, keep the air fresh and healthy, and add a warm glow to the room. I was so impressed with the lamps, i bought family and friends one each and also use the crystal salt for cooking and bathing, its incredible.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('nicky-wed-15th-dec-2010-at-13-05', 'Nicky', 'Wed 15th Dec 2010 at 13:05', 'Thank you so much for doing what you are doing. Service excellent and beautiful products very much needed in these challenging days. Yuletide blessings.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('linda-tue-14th-dec-2010-at-21-42', 'Linda', 'Tue 14th Dec 2010 at 21:42', 'My salt lamp is wonderful. It has a warm glow that welcomes me home on these dark evenings, and enhances the serenity of my space. This was my first salt lamp and I will be purchasing more. The service was excellent and ordering is very easy.', '', NULL, 0, 0, 1, '');
