INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lesley-tue-22nd-jun-2010-at-21-46', 'Lesley', 'Tue 22nd Jun 2010 at 21:46', 'Ordering was easy and the goods arrived at the time agreed. Enjoying the quality of the rock salts.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('gotami-tue-8th-jun-2010-at-19-55', 'Gotami', 'Tue 8th Jun 2010 at 19:55', 'It was very easy to order salt on line, it came quickly and was well packaged. I had some before that I bought at a MindBodySpirit Fair, so I knew what to expect - I don''t use any other salt now, for food or skin. I don''t like giving credit card details over the internet so I was pleased that I could send a cheque instead and as soon as they received it the salt was sent. Salt lamp products make great presents, too.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sister-john-fri-28th-may-2010-at-08-47', 'Sister John', 'Fri 28th May 2010 at 08:47', 'I visited the exhibition yesterday and bought 4 Salty Lamps and several salt balls. I am delighted with the effect of the lamps which will be used for meditation and prayer sessions. I also found a gong and beater for the same praying sessions. I bought a CD of calm Meditative music for prayer slide shows I am making. All in all a very good day and make God bless your work. Thank you.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('khaleda-tue-18th-may-2010-at-16-55', 'Khaleda', 'Tue 18th May 2010 at 16:55', 'My first experience with the salt products was from Anthea Kisson [Anisa]. She recommended the bath salts for my daughters eczema which worked wonders on her skin. Anthea also introduced the edible salts to me and we have incoporated this to our daily intake of vitamins and minerals. I also use the salty water as a face toner its great for dark eye circles. Overall the products compliment Antheas cupping treatment for miind, body and soul [www.nhnf.co.uk].', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
