INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sheila-tue-30th-mar-2010-at-17-36', 'Sheila', 'Tue 30th Mar 2010 at 17:36', 'My friend and I visited the Mind, Body and Soul expo at Brentwood.. we purchased 3 rock salt candle holders. I am so impressed with the product, we are even using a two for candle meditations in Circle.. thank you so much for introducing us to your natural products.', '', NULL, 0, 0, 1, '');
