INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jo-tibble-thu-11th-feb-2010-at-10-05', 'jo tibble', 'Thu 11th Feb 2010 at 10:05', 'I am very pleased with my salt lamp its beutiful, i have put it in my sons bedroom as he has asthma i shall be buying more for around the house so we can all benifit from these lovely lamps!', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('j-sutton-wed-10th-feb-2010-at-10-30', 'j sutton', 'Wed 10th Feb 2010 at 10:30', 'very pleased with the service i received and the quality of the products.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('mel-sun-7th-feb-2010-at-12-56', 'Mel', 'Sun 7th Feb 2010 at 12:56', 'Thank you for the lovely lamp and candle holders which my family loved as their Xmas present. Having seen the lamp \''in action\'' I am now very tempted to get one for myself. Great value for money too.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('zoe-fri-29th-jan-2010-at-12-27', 'Zoe', 'Fri 29th Jan 2010 at 12:27', 'I recently found your product(himalayan bath crystals) on a stall in Winter Wonderland in London at Christmas. I suffer from a disease called Hidredenitis Supporativa this is a horrible disease that causes painful lesions in the skin generally at the tops of my legs and stomach area. I can cope with these lesions but what I cant cope with is the horrendous itchy skin where the tracts from these lesions connect under the skin. I used to use aloe vera gel to try to calm the itch but it wasnt very successful. When I first saw the bath crystals I thought that it might not work as I have tried a number of things to stop the itching, but gave it a go. I am so impressed the itch has stopped and although it has not stopped the lesions I feel so much better as I can get to sleep without having to scratch so much it took the skin off.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('briony-thu-28th-jan-2010-at-10-31', 'Briony', 'Thu 28th Jan 2010 at 10:31', 'So far i have bought 6 lamps as gifts and everyone agrees they are amazingly wonderful! They are stunning and they help the health and wellbeing of my loved ones too, great! Much Love and thanks to everyone at salty lamps xx', '', NULL, 0, 0, 1, '');
