INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('joanne-lees-thu-21st-jan-2010-at-18-42', 'Joanne Lees', 'Thu 21st Jan 2010 at 18:42', 'Bougth two tea light holders and a lamp. Great products. Only issue with delivery as I requested items to be left in my porch as per the delivery form but was then told this was not available! I was then told I would be charged for re:delivery. Satisfacorily resolved in the end.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sue-sat-16th-jan-2010-at-14-53', 'Sue', 'Sat 16th Jan 2010 at 14:53', 'Bought the candle holders with the buy three get one free offer, they were delivered quickly and great value. Kept two and they are brilliant gave the others as Xmas presents and they loved them too. Will be ordering again as they make excellent presents.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('fiona-fri-15th-jan-2010-at-22-49', 'Fiona', 'Fri 15th Jan 2010 at 22:49', 'Brought 2 tea light holders in London, decided to buy a lamp and lights for all my friends and family, I love them.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jill-hood-fri-15th-jan-2010-at-20-47', 'jill hood', 'Fri 15th Jan 2010 at 20:47', 'I bought 6 candles and one lamp as christmas presents. They were delivered very quickly and everyone loved them. thank you. very impressed that despite the weight of the parcel this did not incur any extra postage cost. will definitely recommend this site.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('julie-fri-15th-jan-2010-at-17-59', 'Julie', 'Fri 15th Jan 2010 at 17:59', 'I bought a lamp as a Christmas gift for my Mother who suffers terribly from Migraine...15th of January 2010 and no reports of any Migraine up to now, which is brilliant.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('gail-macpherson-fri-15th-jan-2010-at-16-16', 'Gail MacPherson', 'Fri 15th Jan 2010 at 16:16', 'Bought my first lamp at the Manchester MB & Spirit festival. Loved it so much I bought my relatives one each - they said it was their favourite present by far and requested another one each last Christmas. Then my teenage son wanted one too! Use them every day - thanks Salty Lamps :)', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('richard-parker-fri-15th-jan-2010-at-13-37', 'Richard Parker', 'Fri 15th Jan 2010 at 13:37', 'Nice products. Good, fast service, with products arriving well packed. Many thanks.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('john-dedman-fri-15th-jan-2010-at-13-08', 'john dedman', 'Fri 15th Jan 2010 at 13:08', 'The salty lamp candle holders were a great find on the internet and have enhanced my tables in my pub considerably, especially in the evenings, at a considerable less cost than in certain dubious markets. I will probably be back for more !', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lynsey-evans-thu-17th-dec-2009-at-23-20', 'Lynsey Evans', 'Thu 17th Dec 2009 at 23:20', 'What a wondeful company. I love the fact that someone answers the phone and is extremely helpful and knows there products. I will only buy my candle holders and lamps from here now. A great find on the internet. Best Wishes.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('alexis-the-happiness-centre-fri-16th-oct-2009-at-11-43', 'Alexis - The Happiness Centre', 'Fri 16th Oct 2009 at 11:43', 'Customers love the Himalayan Bath Salts. That product along with the Candle Holders have been consistently best-sellers for us over the past couple of years retail at The Happiness Centre in Shepherds Bush London. We highly recommend stocking the products for any natural healthcare centre. Asim always delivers excellent customer service - thanks for the wonderful products!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('james-bromfield-mon-21st-sep-2009-at-12-22', 'James Bromfield', 'Mon 21st Sep 2009 at 12:22', 'I ordered 4 salt lamps from Salty Lamps and have used one of them every night for the past three nights. The difference in the air quality is incredible! Like the aftermath of a thunderstorm but no rain:-) These lamps are excellent for relaxation and are visually attractive too, everyone should have one.', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('patrick-mon-7th-sep-2009-at-22-54', 'patrick', 'Mon 7th Sep 2009 at 22:54', 'i find the Himalayan salt excellent for detoxing, I must say it is adviseable to be careful with the amount that is put in the bath, I find a handful is safe for a well balanced detox.', '', NULL, 0, 0, 0, 'Medical or air-treatment claim — suppressed under UK ASA guidance for republished testimonials.');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('vanessa-thu-3rd-sep-2009-at-18-12', 'Vanessa', 'Thu 3rd Sep 2009 at 18:12', 'I ordered my salt lamps after seeing them at the Mind Body Spirit festival. The website and service were great and my lamps are wonderfully soothing and restful. They are used practically every day and even my cat loves them! Thanks very much.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('kay-barber-naturallyu-wed-2nd-sep-2009-at-08-57', 'kay barber - naturallyu', 'Wed 2nd Sep 2009 at 08:57', 'Thanks to Asim and \\\''Salty Lamps\\\'' I have now extended my business with lots of happy clients now owning their own salt products. We feel all the products have blended with our strong beliefs of well being perfectly.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('lynsey-evans-tue-1st-sep-2009-at-21-04', 'Lynsey Evans', 'Tue 1st Sep 2009 at 21:04', 'Wonderful service, very quick. Great offers and fantastic quality.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('linda-sun-30th-aug-2009-at-19-20', 'linda', 'Sun 30th Aug 2009 at 19:20', 'The 2 candle holder''s I bought from u provide me with the desired lighting I wanted for my bedroom and lounge area.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jo-milewski-sun-30th-aug-2009-at-17-28', 'Jo Milewski', 'Sun 30th Aug 2009 at 17:28', 'I bought a salt lamp after seeing it at a Christmas Fayre. I bouhgt it from this web site, delivery really good and i am very pleased with it. It is very soothing. Regards JO', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('margaret-duggan-sun-30th-aug-2009-at-10-56', 'Margaret Duggan', 'Sun 30th Aug 2009 at 10:56', 'Asim & his team know the true meaning of customer service - prompt efficient and nothing is too much trouble - superb! I have purchased many candles for colleagues and friends - terrific original presents as well as environmentally helpful and peaceful. The candles are also a great talking point around a dinner table. Thank you Salty Lamps! Warmest Wishes, Margaret', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('sophia-green-sun-30th-aug-2009-at-00-05', 'Sophia Green', 'Sun 30th Aug 2009 at 00:05', 'I am really pleased with my salty lamps. I got a small lamp which sits next to my computer and I keep it on most of the time. It is very relaxing. I also got two candle holders as part of the deal and the light they give off is absolutely beautiful - they are especially lovely when all other lights are off. Thank you. I have been very satisfied with the service.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('andy-sat-29th-aug-2009-at-05-58', 'Andy', 'Sat 29th Aug 2009 at 05:58', 'Bought Salty lamp products for not only myself but also for all my family and everyone loves them. Great company and worth your support', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('debbie-b-thu-11th-jun-2009-at-17-34', 'Debbie B', 'Thu 11th Jun 2009 at 17:34', 'Excellent products and extremely fast delivery. I will use Salty Lamps again.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jaki-mon-8th-jun-2009-at-21-09', 'Jaki', 'Mon 8th Jun 2009 at 21:09', 'I choose the lamp and purchased the same himalayan crystals at the exhibition in London in May 2009. The service and prompt delivery was very much appreciated . Thank You', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('ash-mon-11th-may-2009-at-17-44', 'Ash', 'Mon 11th May 2009 at 17:44', 'Your Himalayan bath salts were fantastic: I felt refreshed and invigorated after my dip.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('marilyn-murray-wed-11th-mar-2009-at-15-49', 'marilyn murray', 'Wed 11th Mar 2009 at 15:49', 'We just love our salty lamp!! My sister bought it for us as a gift---in fact we love it so much that we want to buy another for the bedroom plus a few tealights.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('heather-sat-21st-feb-2009-at-22-42', 'heather', 'Sat 21st Feb 2009 at 22:42', 'Item was a great hit as a present. thankyou!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jennifer-standage-sun-15th-feb-2009-at-15-18', 'Jennifer Standage', 'Sun 15th Feb 2009 at 15:18', 'Thank you for sending the 3 salty lamps after our telephone conversation about paying for them. I found your website method of paying confusing and thought I could ONLY pay if I had a Paypal account which I dont. There did not seem to be any other options and I didn\''t dare to click on that box to go on to the options with credit cards. But on the phone I paid you with my credit card and all is well and the lamps arrived.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('aimee-thu-12th-feb-2009-at-17-25', 'aimee', 'Thu 12th Feb 2009 at 17:25', 'I love my salty lamp candle holder, it looks beautiful when lit and sets a calming mood. I''m sorry there''s no more in stock cos i''d like another one :-(', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('doreen-day-thu-12th-feb-2009-at-16-56', 'Doreen Day', 'Thu 12th Feb 2009 at 16:56', 'I was very pleased with the service I received, but I wish you could replenish your stock as I wished to buy one as Birthday Present and as you were out of stock of practically every item I had to purchase something else, as the Birthday has now passed!!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('peter-tonkin-thu-12th-feb-2009-at-16-36', 'Peter Tonkin', 'Thu 12th Feb 2009 at 16:36', 'The salt lamp we bought at the Spirit of Christmas exhibition is a really lovely item. And, the after sales service we experienced was first class.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('hazel-norris-sun-4th-jan-2009-at-17-12', 'hazel Norris', 'Sun 4th Jan 2009 at 17:12', 'I brought your salty lamps at the Christmas market in hide part. I first brought 2 for myself and partner but when i got home and used them I was so amazed by how much they have helped us,I went back a week later and got 6 more for friends and family members as Christmas gifts. will defiantly be buying more things. thank you from a very very happy customer.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('victoria-cersosimo-mon-15th-dec-2008-at-18-54', 'Victoria Cersosimo', 'Mon 15th Dec 2008 at 18:54', 'Thank you very much for my order. The lamps are beautiful. Great service, highly recommended. Thanks again!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('gail-fri-21st-nov-2008-at-20-05', 'Gail', 'Fri 21st Nov 2008 at 20:05', 'I recently bought my pyramid salty lamp at the Mind, Body, Spirit Manchester. I absolutely love it and shall order my relatives some for Christmas for a unique gift idea.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('suzanne-newson-thu-20th-nov-2008-at-15-19', 'suzanne newson', 'Thu 20th Nov 2008 at 15:19', 'My salty lamps and candle holder are very nice, i have them in every room, my daughter is hoping to get one for her bedroom for xmas.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('jo-farrow-mon-17th-nov-2008-at-17-32', 'Jo Farrow', 'Mon 17th Nov 2008 at 17:32', 'I am very pleased with the lamps I have purchased, I think they look lovely and they are healthy too! I have lots of friends that I am hoping are going to like them as they are ideal birthday presents for people who have everything. Thanks very much for the prompt service.', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('leanne-siu-fri-14th-nov-2008-at-09-56', 'Leanne Siu', 'Fri 14th Nov 2008 at 09:56', 'Excellent customer service and fast delivery. The free bath salts were a bonus! Thank-you!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('serena-chancellor-tue-14th-oct-2008-at-18-28', 'Serena Chancellor', 'Tue 14th Oct 2008 at 18:28', 'I got my lamps yesterday,and I am very pleased with them. They are wonderful nightlights for the children and look lovely around the house. I shall definately be ordering some more for xmas presents!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('iain-beveridge-tue-30th-sep-2008-at-11-41', 'Iain Beveridge', 'Tue 30th Sep 2008 at 11:41', 'Just ordered our fourth lot of bath salts - they are wonderful!! My wife has very sensative skin and cant use bubble bath or normal perfumed bath salts but adores these Himilayian Bath salts - you really do feel refreshed and revived - mind you we do put a good handfull in each time. No doubt back for more soon!!', '', NULL, 0, 0, 1, '');
INSERT OR IGNORE INTO reviews (id, name, date_text, quote, proof, rating, featured, featured_order, display, flagged_reason) VALUES ('nicky-tolson-tue-23rd-sep-2008-at-11-00', 'Nicky Tolson', 'Tue 23rd Sep 2008 at 11:00', 'I''m about to place an order for my FIFTH salty lamp - the big football sized one. So far they have proven to be fantastic. One was given as a wedding present to friends who have everything - and the essence of the salty lamp resonated well with them, as they love natural elements of our world in their home. Another friend has purchased two - she''s almost blind and the gentle, soothing light is extremely calming for her. She too will be ordering more and has recommended Salty Lamps to her friends. Thank you Asim, for bringing these to us.', '', NULL, 0, 0, 1, '');

-- --------------------------------------------------------------------------
-- Per-theme selling copy, reassurance bullets and support images
-- --------------------------------------------------------------------------
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('lamp', '{name} brings a warm amber glow to bedrooms, lounges, desks, treatment rooms, and gift shelves. Each piece is cut from natural Himalayan rock salt, so the colour, shape, and surface character feel individual rather than factory-perfect.', 'Where it works best', '["Bedside tables, shelves, desks, lounges, and calm corners.","Gift buying when the recipient likes warm, natural decor.","Spa, wellness, or reception areas that need softer ambient light."]', 'Care and setup', '["Keep the salt dry and away from damp rooms or wet surfaces.","Use compatible lamp parts and check bulbs or cables before replacing.","Expect natural variation in tone, texture, and weight."]', 'A simple way to add warmth, texture, and atmosphere without making the room feel overly decorated.', '["Includes the lamp parts listed on the product card where applicable.","Natural rock salt varies in colour, texture, and weight.","Keep dry and use with compatible bulbs and cables."]', 'featured-2');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('holder', '{name} is made for small moments of glow: dining tables, bedside shelves, spa rooms, gifting, and relaxed evening settings. The natural salt surface gives every holder its own tone and mineral texture.', 'Best used for', '["Tealight ambience for dining tables, shelves, bedrooms, and spa spaces.","Low-risk gifting when you want something natural and decorative.","Grouped displays with lamps, bowls, or other saltware."]', 'Care and safety', '["Keep dry and wipe with a soft cloth when needed.","Use suitable tealights and place on a stable, heat-safe surface.","Colour and surface markings vary because the holder is natural rock salt."]', 'Small, giftable pieces that create an immediate warm glow without needing a large lamp.', '["Made from natural Himalayan rock salt, so every holder is slightly different.","Designed for tealight-style ambience and giftable table settings.","Keep dry and wipe clean with a soft cloth."]', 'featured-1');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('kitchen', '{name} is designed for kitchens, serving, food display, and thoughtful hosting. It gives food presentation a natural pink salt character while still feeling practical for counters, tables, and giftable kitchen ranges.', 'How to use it', '["Serve, present, chill, or display food depending on the selected shape and size.","Use for kitchen counters, table settings, food gifting, or hospitality presentation.","Pair with culinary salt, bowls, or serving pieces for a fuller saltware set."]', 'Care before buying', '["Rinse or wipe according to the supplied care guidance and dry thoroughly.","Saltware naturally changes with heat, moisture, food contact, and repeated use.","Choose the size, grade, or shape that matches how you plan to serve or cook."]', 'A more memorable kitchen piece for buyers who want food presentation to feel tactile, natural, and conversation-worthy.', '["Food and serving items should be rinsed or wiped according to the supplied care guidance.","Saltware naturally changes with use, moisture, and heat.","Choose a size or grade before adding when selectors are shown."]', 'featured-3');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('bricks', '{name} is suited to salt wall features, wellness rooms, spa projects, interiors work, and repeat trade supply. It is a practical route for buyers who need natural salt material with a project or display purpose.', 'Project fit', '["Salt wall features, wellness rooms, spa areas, and interior displays.","Retail, trade, or hospitality buyers planning repeat supply.","Specification conversations where size, quantity, and finish matter."]', 'Planning notes', '["Confirm sizes, quantities, and lead times before large orders.","Keep salt materials dry before installation or display.","Ask for trade support when matching a project schedule or repeat stock need."]', 'Built for buyers who need confidence before committing to a larger project or repeat order.', '["Suitable for project enquiries, salt wall features, and repeat trade supply.","Confirm size, quantity, and lead time before large orders.","Trade buyers can ask for project quoting before checkout."]', 'featured-1');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('equestrian', '{name} gives horses, cattle, fields, yards, and smallholdings a simple natural salt option. It is made for practical repeat buying rather than decorative display.', 'Yard and field use', '["Fields, stables, yards, smallholdings, and animal mineral routines.","Single purchases or repeat supply for busier yards.","Buyers who want a simple natural salt lick without complicated presentation."]', 'Buying notes', '["Choose the correct size or pack quantity where options are shown.","Store dry before use and place appropriately for the animal and setting.","Ask about bulk supply if you are buying for a yard, field, or repeat routine."]', 'A straightforward mineral-salt product for buyers who care more about reliability than decoration.', '["Choose size and pack quantity before adding when selectors are shown.","Suitable for horses, cattle, fields, yards, and smallholding routines.","Bulk enquiries are available for repeat yard supply."]', 'featured-5');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('relaxation', '{name} supports spa, bath, massage, body-care, and sensory routines with the natural mineral character of Himalayan salt. It works well for personal use, wellness gifts, and treatment-room ranges.', 'Wellness use', '["Spa, bath, massage, relaxation, or body-care routines depending on the item.","Gift bundles for buyers who want calm, tactile, natural products.","Treatment rooms or wellness retail displays."]', 'Care guidance', '["Keep dry between uses and follow the supplied care notes.","Texture, colour, and finish vary naturally from piece to piece.","Choose the format that matches the intended routine or treatment."]', 'A tactile wellness product with enough natural variation to feel personal and giftable.', '["Made for sensory, spa, bath, or body-care use depending on the selected item.","Natural salt products vary in texture and finish.","Keep products dry between uses and follow supplied care guidance."]', 'featured-4');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('accessory', '{name} helps keep compatible salt lamps working safely and conveniently. It is a practical replacement item for buyers who already own a lamp or need spare parts for repeat use.', 'Compatibility first', '["Replacement parts for compatible salt lamps.","Keeping spare bulbs or cables ready for home, retail, or trade use.","Solving a practical lamp issue without replacing the full product."]', 'Before ordering', '["Check compatibility with your lamp before buying.","Match bulb, cable, plug, and holder requirements carefully.","Ask the team if you are unsure which fitting you need."]', 'A practical support item that protects the value of the lamp you already own.', '["Check compatibility with your lamp before ordering.","Bulbs and cables are practical replacement parts for existing lamps.","Ask the team if you are unsure which fitting you need."]', 'featured-5');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('deal', '{name} is made for easy gifting, starter sets, and better-value bundles. It helps buyers choose quickly when they want a warm salt product without comparing every individual item.', 'Why choose the bundle', '["Quick gift buying when you want a ready-made salt product set.","Starter purchases for homes, desks, lounges, and shelves.","Better value when buying more than one piece."]', 'What to expect', '["Check the included items before ordering.","Natural salt pieces vary in colour, texture, and weight.","Keep items dry and follow the care notes for the product type included."]', 'A simpler route for buyers who want the Salty Lamps look with less decision fatigue.', '["Bundle offers make gift buying simpler.","Check included items before ordering.","Natural salt pieces vary, so each bundle has its own tone and texture."]', 'featured-2');
INSERT OR IGNORE INTO content_themes (theme, lede_template, use_title, uses, care_title, care, promise, reassurance, proof_review_id) VALUES ('panel', '{name} is illuminated Himalayan salt wall art — ancient rock salt carved into a hand-finished solid-wood frame. Each panel is a unique piece of nature, with mineral veining that ranges from pale pink to deep orange, and a warm glow that changes the feel of a room the moment it is lit.', 'Where it works best', '["Living rooms, bedrooms, and home offices that want a warmer, calmer feel.","Gyms, yoga studios, and wellness spaces where a soft glow sets the tone.","Reception areas and interiors projects that want a natural statement piece."]', 'Setup and care', '["Keep the panel dry and wipe gently with a dry cloth.","Avoid prolonged exposure to humidity — mount securely with the supplied fittings.","Natural variation in colour, veining, and texture is normal; no two panels are alike."]', 'A unique piece of nature, framed by hand, bringing warmth and timeless character to any wall.', '[]', 'featured-1');

