INSERT OR IGNORE INTO collections (slug, name, short_name, eyebrow, heading, description, hero_intro, hero_video, hero_poster, theme, background, trade_eyebrow, trade_heading, trade_body, trade_cta, sort_order, visible) VALUES ('home-gifts', 'Home, gifts and glow', 'Home and gifts', 'Everyday warmth', 'Lamps, holders, gifts, and easy home glow.', 'Warm-room products for bedrooms, desks, lounges, shelves, and simple gifting.', '["There''s a particular kind of calm that arrives when a room glows amber instead of glaring white. Our hand-finished ",{"hl":"salt lamps and candle holders"}," turn bedrooms, desks, and lounges into spaces that feel warmer the moment they''re lit — and they make ",{"hl":"quietly thoughtful gifts"},". Every piece is carved from natural Himalayan rock salt, so ",{"hl":"no two are ever quite alike"},"."]', '/media/video/collection/home-gifts-hero-16x9.mp4', '/media/video/collection/home-gifts-hero-poster-16x9.jpg', 'lamp', '/media/yoga-room.png', 'Shops, salons and interior buyers', 'Trade accounts for retail and hospitality.', 'We supply boutique gift shops, hotel amenities buyers, and salon chains. Contact us for trade pricing, minimum orders, and lead times.', 'Open a trade enquiry', 10, 1);
INSERT OR IGNORE INTO collections (slug, name, short_name, eyebrow, heading, description, hero_intro, hero_video, hero_poster, theme, background, trade_eyebrow, trade_heading, trade_body, trade_cta, sort_order, visible) VALUES ('kitchen-food', 'Kitchen and food', 'Kitchen', 'Cooking and serving', 'Saltware, platters, bowls, and pantry salt.', 'Food and hosting products for kitchens, counters, table settings, and gifts.', '["Salt should be something you can see, taste, and serve from. Our ",{"hl":"culinary-grade Himalayan salt"},", hand-cut platters, and serving bowls bring ",{"hl":"genuine mineral character"}," to everyday cooking and unhurried hosting alike. Sear, chill, plate, and present on a material that is ",{"hl":"as striking on the table as in the pan"},"."]', '/media/video/collection/kitchen-food-hero-16x9.mp4', '/media/video/collection/kitchen-food-hero-poster-16x9.jpg', 'kitchen', '/media/kitchen-setup.png', 'Restaurants, caterers and chefs', 'Case and pallet supply for professional kitchens.', 'Culinary-grade Himalayan salt, cooking platters, and serving pieces at trade pricing for restaurants, food service, and hospitality.', 'Request catering trade pricing', 20, 1);
INSERT OR IGNORE INTO collections (slug, name, short_name, eyebrow, heading, description, hero_intro, hero_video, hero_poster, theme, background, trade_eyebrow, trade_heading, trade_body, trade_cta, sort_order, visible) VALUES ('horses-farm', 'Horses and farm', 'Horses and farm', 'Field and yard supply', 'Salt licks and bulk-ready animal mineral products.', 'Simple routes for horse owners, yards, smallholders, and equestrian suppliers.', '["Animals know what they need. A ",{"hl":"natural Himalayan salt lick"}," gives horses, ponies, and cattle a simple mineral source they can return to in the field or yard — ",{"hl":"no fuss, no additives"},", just natural rock salt for everyday routines. Single licks or bulk-ready supply for busy yards."]', '/media/video/collection/horses-farm-hero-16x9.mp4', '/media/video/collection/horses-farm-hero-poster-16x9.jpg', 'equestrian', '/media/home-horse-salt-lick-generated.png', 'Yards, equestrian centres and farms', 'Bulk salt lick supply for busy yards.', 'Trade pricing on pallet quantities for equestrian centres, livery yards, and farms with multiple horses, cattle, or sheep.', 'Ask about bulk lick pricing', 30, 1);
INSERT OR IGNORE INTO collections (slug, name, short_name, eyebrow, heading, description, hero_intro, hero_video, hero_poster, theme, background, trade_eyebrow, trade_heading, trade_body, trade_cta, sort_order, visible) VALUES ('trade-spa', 'Trade supply', 'Trade and wellness', 'Projects and repeat supply', 'Salt walls, spa products, and trade-friendly ranges.', 'Bulk supply for spas, retailers, and interiors projects.', '["Wellness spaces sell a feeling before they sell anything else. ",{"hl":"Backlit salt-brick walls"},", warm massage stones, and mineral bath salts let spas, treatment rooms, and interiors projects build that ",{"hl":"sense of calm"}," into the room itself. ",{"hl":"Trade-friendly pricing and repeat supply"}," make it easy to specify once and reorder with confidence."]', '/media/video/collection/trade-spa-hero-16x9.mp4', '/media/video/collection/trade-spa-hero-poster-16x9.jpg', 'bricks', '/media/home-spa-salt-room-generated.png', 'Spas, wellness rooms and interiors', 'Specification, project quoting, and repeat supply.', 'Salt wall bricks, massage stones, and bath salts for spa specification, wellness room fit-outs, and high-volume treatment centres.', 'Request a project quote', 40, 1);
INSERT OR IGNORE INTO collections (slug, name, short_name, eyebrow, heading, description, hero_intro, hero_video, hero_poster, theme, background, trade_eyebrow, trade_heading, trade_body, trade_cta, sort_order, visible) VALUES ('aura-collection', 'The Aura Collection', 'Aura Collection', 'Illuminated wall art', 'Illuminated Himalayan salt wall art, framed by hand.', 'Luxury backlit salt panels in hand-finished wood frames — warm, unique wall art for homes, gyms, and studios.', '["The Aura Collection is ",{"hl":"illuminated Himalayan salt wall art"}," — carved from ancient rock salt formed over millions of years, so ",{"hl":"every panel is unique"},", with natural mineral veining from pale pink to deep orange. Each piece is set in a ",{"hl":"hand-finished solid-wood frame"}," with mitred corners, pairs beautifully with wood, stone, linen, and plants, and comes in a range of sizes — from a single accent panel to a full statement wall, at home, in the studio, or in reception."]', '/media/video/collection/aura-collection-hero-16x9.mp4', '/media/video/collection/aura-collection-hero-poster-16x9.jpg', 'panel', '/media/aura-collection-lifestyle.jpg', '', '', '', '', 50, 1);

