INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('home-gifts:gift-sets-offers', 'home-gifts', NULL, 'gift-sets-offers', 'Gift sets & offers', 'Starter bundles and easy gift buys with a clear value story.', 'Best for shoppers who want a complete present without comparing every shape.', 'Lead with bundles because gift-led visitors usually need confidence and speed more than a deep catalogue.', '/media/live-site-products/deal-lamp-candle-gemini.jpg', 'deal', 'special-deal', '{"categories":{"any":["special-deal"]}}', 10);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('home-gifts:salt-lamps', 'home-gifts', NULL, 'salt-lamps', 'Salt lamps', 'Warm-glow lamps for bedrooms, counters, lounges, and gifts.', 'Choose the main glow piece for a bedside table, desk, shelf, or cosy corner.', 'Make natural and bestseller lamps the anchor, then let shaped lamps act as decorative alternatives.', '/media/live-site-products/lamp-natural-gemini.jpg', 'lamp', 'salt-lamps', '{"categories":{"any":["salt-lamps"],"none":["special-deal"]}}', 20);
