INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('home-gifts:candle-holders', 'home-gifts', NULL, 'candle-holders', 'Candle holders', 'Giftable tealight holders for cosy rooms, spas, and tables.', 'Small amber accents for dinner tables, shelves, gift boxes, and quiet evenings.', 'Treat holders as affordable add-ons and small gifts, not as direct competitors to lamps.', '/media/live-site-products/holder-heart-gemini.jpg', 'holder', 'candle-holders', '{"categories":{"any":["candle-holders"],"none":["special-deal"]}}', 30);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('home-gifts:accessories', 'home-gifts', NULL, 'accessories', 'Accessories', 'Replacement bulbs and cables for compatible salt lamps.', 'Keep an existing lamp lit with the right cable or replacement bulb.', 'Keep accessories at the end so they support owners without interrupting gift and decor browsing.', '/media/live-site-products/accessory-bulb-gemini.jpg', 'accessory', 'accessories', '{"categories":{"any":["accessories"]}}', 40);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('kitchen-food:cookware-serving', 'kitchen-food', NULL, 'cookware-serving', 'Cookware & serving', 'Platters and bowls to cook, chill, and serve on pure salt.', 'Saltware for grazing boards, searing, chilling, and table presentation.', 'Start with serving pieces because they are visual, giftable, and easier to understand at a glance.', '/media/live-site-products/platter-kitchen-gemini.jpg', 'kitchen', 'rock-salt-pantry-items', '{"tags":{"any":["hosting","serving"]}}', 10);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('kitchen-food:pantry-barware', 'kitchen-food', NULL, 'pantry-barware', 'Pantry & barware', 'Culinary salt and salt barware for everyday cooking and hosting.', 'Pink mineral salt and smaller pieces for seasoning, drinks, and easy hosting.', 'Use pantry items as lower-friction add-ons after the shopper understands the food range.', '/media/live-site-products/salty-chef-pouch-gemini.jpg', 'kitchen', 'rock-salt-pantry-items', '{"categories":{"any":["rock-salt-pantry-items"]}}', 20);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('horses-farm:stable-field-licks', 'horses-farm', NULL, 'stable-field-licks', 'Stable & field licks', 'Single mineral salt licks for horses, cattle, fields, and yards.', 'A simple natural lick for a paddock, stable, pony, or smallholding routine.', 'Show the single lick first because it answers the basic buyer need before pack-size decisions.', '/media/live-site-products/lick-product-clean-gemini.jpg', 'equestrian', 'equestrian-salt-licks', '{"categories":{"any":["equestrian-salt-licks"],"none":["special-deal"]}}', 10);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('horses-farm:yard-bulk-supply', 'horses-farm', NULL, 'yard-bulk-supply', 'Yard & bulk supply', 'Bulk-ready salt lick supply for busier yards and repeat orders.', 'A practical route for keepers who need dependable repeat stock.', 'Separate bulk supply so trade and yard buyers see repeat-order value without confusing single-item shoppers.', '/media/live-site-products/lick-field-scene-gemini.jpg', 'equestrian', 'equestrian-salt-licks', '{"categories":{"all":["equestrian-salt-licks","special-deal"]}}', 20);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('trade-spa:salt-bricks-walls', 'trade-spa', NULL, 'salt-bricks-walls', 'Salt bricks & walls', 'Salt wall bricks and feature-wall materials for trade buyers.', 'Create a glowing wall feature for reception areas, treatment rooms, and projects.', 'Lead with project materials because trade buyers need specification clarity before browsing spa retail pieces.', '/media/live-site-products/salt-bricks-clean-gemini.jpg', 'bricks', 'rock-salt-bricks', '{"categories":{"any":["rock-salt-bricks"]}}', 10);
INSERT OR IGNORE INTO collection_sections (id, collection_slug, parent_id, anchor_id, title, descriptor, card_text, recommendation, image, theme, category_slug, rule, sort_order) VALUES ('trade-spa:spa-relaxation', 'trade-spa', NULL, 'spa-relaxation', 'Spa & relaxation', 'Massage, bath, and body-care salt for wellness spaces.', 'Retail-friendly wellness pieces for treatment rooms, bath rituals, and shelves.', 'Place relaxation products after salt walls so they feel like retail add-ons for wellness and spa buyers.', '/media/live-site-products/massage-stones-gemini.jpg', 'relaxation', 'himalayan-salt-massage-relaxation-products', '{"categories":{"any":["himalayan-salt-massage-relaxation-products"]}}', 20);

