INSERT OR IGNORE INTO content_pages (path, title, body, meta_description) VALUES ('/privacy-policy', 'Privacy Policy', '["Salty Lamps Ltd only collects the information needed to answer enquiries, process orders, and send requested updates.","Newsletter subscribers can opt out of marketing emails at any time by contacting info@saltylamps.co.uk.","Customer details are handled carefully and are not sold to third parties."]', '');
INSERT OR IGNORE INTO content_pages (path, title, body, meta_description) VALUES ('/terms-and-conditions', 'Terms and Conditions', '["Orders are subject to product availability, confirmed pricing, and successful payment or agreed invoice terms.","Natural Himalayan salt products vary in tone, texture, and shape because every piece is cut from natural rock salt.","Use products according to the care guidance supplied and keep salt items away from excess moisture."]', '');
INSERT OR IGNORE INTO content_pages (path, title, body, meta_description) VALUES ('/return-refund-policy', 'Returns and Refund Policy', '["If an item arrives damaged or incorrect, contact Salty Lamps Ltd promptly with your order details and photographs where relevant.","Returns and exchanges are reviewed against product condition, timing, and the nature of the item ordered.","Trade, custom, and bulk orders may require separate return arrangements."]', '');

