INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-steps-1', 'process-steps', 'Mine', 'Mined rock salt', 'Raw rock salt is extracted from mines and loaded onto trucks for the first leg of the journey.', '', NULL, NULL, 10);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-steps-2', 'process-steps', 'Sort', 'Warehouse sorting', 'The material reaches the Karachi warehouse, where it is washed, dried, and separated by colour and quality.', '', NULL, NULL, 20);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-steps-3', 'process-steps', 'Cut', 'Cut and shaped', 'Rock salt is cut into natural lamps, specific shapes, bowls, bricks, tiles, and other product forms.', '', NULL, NULL, 30);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-steps-4', 'process-steps', 'Finish', 'Hand finished', 'Each cut piece is carefully hand-crafted by skilled workmen so the natural material keeps its character.', '', NULL, NULL, 40);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-steps-5', 'process-steps', 'Pack', 'Packed for export', 'Finished pieces are shrink wrapped, boxed, palletized, and sent to the port for export.', '', NULL, NULL, 50);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-proof-points-1', 'process-proof-points', 'Handled', 'Real labour at every stage', 'The film shows the physical movement behind the product: lifting, rinsing, sorting, cutting, finishing, and packing.', '', NULL, NULL, 10);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-proof-points-2', 'process-proof-points', 'Checked', 'Natural material, judged piece by piece', 'Colour, clarity, size, grain, and fractures all affect what each piece can become.', '', NULL, NULL, 20);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-proof-points-3', 'process-proof-points', 'Finished', 'Machine cut, human refined', 'The work keeps the irregular mineral character while making each item ready for use or display.', '', NULL, NULL, 30);
INSERT OR IGNORE INTO content_list_items (id, list_key, label, title, text, href, metric_value, metric_percent, sort_order) VALUES ('process-proof-points-4', 'process-proof-points', 'Arrived', 'From workshop to home', 'The close is not another step list: it brings the journey home as a finished object with warmth and presence.', '', NULL, NULL, 40);
